import random, time

class TransientError(Exception):
    pass

def retry(fn, retries=4, base=0.5, cap=8.0, sleep=time.sleep, rand=random.random):
    for attempt in range(retries + 1):
        try:
            return fn()
        except TransientError:
            if attempt == retries:
                raise
            sleep(rand() * min(cap, base * 2 ** attempt))

